// Filtre projets actifs + construit TEAM_STATE_JSON
const projectsRaw = $('Lire project_queue').all().map(i => i.json);
const teamRaw = $('Lire team_state').all().map(i => i.json);

const projects = projectsRaw
  .filter(p => ['new', 'in_progress'].includes(String(p.status || '').toLowerCase()))
  .map(p => ({
    id: p.id,
    client: p.client_name,
    niche: p.niche,
    complexity: p.estimated_project_complexity,
    deadline: p.deadline || null,
    current_status: p.status,
    summary: (p.client_brief_summary || '').slice(0, 200)
  }));

const team = teamRaw.map(t => ({
  name: t.name,
  role: t.role,
  current_load_pct: Number(t.current_load_pct) || 0,
  unavailable_days: String(t.unavailable_days || '').split(',').map(s => s.trim()).filter(Boolean)
}));

const run_id = 'run_' + Date.now();

return [{
  json: {
    run_id,
    team,
    projects,
    incoming_leads_to_review: 0,
    drafts_to_validate: 0
  }
}];

