// Parse + explode 1 ligne par projet pour append weekly_recommendations
const llm = $json;
let parsed = {};
try {
  const c = llm && llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content;
  if (!c) throw new Error('NO_CONTENT');
  parsed = JSON.parse(c);
} catch (e) {
  parsed = { table: [], weekly_priorities: [], overload_warnings: [], _llm_error: String(e && e.message || e) };
}

const run_id = $('Build TEAM_STATE_JSON').first().json.run_id;
const now = new Date().toISOString();
const projectsContext = $('Build TEAM_STATE_JSON').first().json.projects || [];

const rows = (parsed.table || []).map(t => {
  const ctx = projectsContext.find(p => p.id === t.project_id) || {};
  return {
    json: {
      ts: now,
      run_id,
      project_id: t.project_id,
      client: t.client || ctx.client || '',
      complexity: t.complexity || ctx.complexity || '',
      assigned_to: t.assigned_to || '',
      estimated_hours: t.estimated_hours || '',
      priority: t.priority || '',
      reason: (parsed.overload_warnings || []).map(w => w.reason).join(' | ') || ''
    }
  };
});

// Si aucune ligne (LLM erreur ou aucun projet), on retourne au moins une ligne vide pour log
if (rows.length === 0) {
  return [{
    json: {
      ts: now,
      run_id,
      project_id: '',
      client: '',
      complexity: '',
      assigned_to: '',
      estimated_hours: '',
      priority: '',
      reason: parsed._llm_error ? ('llm_error: ' + parsed._llm_error) : 'no_active_projects'
    }
  }];
}
return rows;
